import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.QWVCgkrI.js";const s="/study/images/io/sync-async-timeline.svg",i="/study/images/io/async-request-lifetime.svg",m=JSON.parse('{"title":"非同期I/O — 要求・完了・バッファの寿命","description":"","frontmatter":{"title":"非同期I/O — 要求・完了・バッファの寿命","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"非同期ファイル読み取りを要求・完了通知・結果回収に分ける。WindowsのOVERLAPPED、pendingと即時完了、キャンセル後の寿命、C#のReadAsyncとawait、ゲームでの完了後処理を区別する。","aliases":["asynchronous I/O","非同期I/O","overlapped I/O","OVERLAPPED","ERROR_IO_PENDING","GetOverlappedResult","CancelIoEx","IRP","IOCP","ReadAsync","await","ValueTask","continuation","継続","backpressure","バックプレッシャー"],"verification":"一次資料照合（2026-11-04）"}},"headers":[],"relativePath":"os/asynchronous-file-io.md","filePath":"os/asynchronous-file-io.md"}'),n={name:"os/asynchronous-file-io.md"};function d(c,e,l,p,h,f){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="非同期i-o-—-要求・完了・バッファの寿命" tabindex="-1">非同期I/O — 要求・完了・バッファの寿命 <a class="header-anchor" href="#非同期i-o-—-要求・完了・バッファの寿命" aria-label="Permalink to &quot;非同期I/O — 要求・完了・バッファの寿命&quot;">​</a></h1><p>非同期I/Oでは読み取りの要求と、結果を使えるようになる時点が分かれます。要求後に別の仕事へ進める場合がありますが、その間もバッファや要求情報はI/Oで使われ得ます。呼出しから戻っただけで再利用・破棄してはいけません。</p><p>ここではWindowsの通常ファイルを対象に、C++のOVERLAPPED I/OとC#の<code>FileStream.ReadAsync</code>を説明します。他OSやすべてのランタイムが同じ内部方式とはしません。ファイル位置、実際に読めた数、キャッシュ、byteとデコードの区別は<a href="/study/os/file-read-journey.html">ファイルを読む仕組み</a>を参照してください。</p><p><a href="/study/network/tcp-sockets.html">TCPソケット</a>で非blockingソケットを<code>select</code>／<code>Poll</code>で待つ方法は、操作できる状態を調べる<strong>readiness</strong>の方式です。発行済み要求の完了を受け取る方式と区別します。読取り可能という通知だけでデータの到着やアプリのメッセージ完成を決めず、実際の受信結果でデータ・EOF・エラーを判断します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-select" target="_blank" rel="noreferrer">Microsoft: select</a>、<a href="https://learn.microsoft.com/en-us/dotnet/api/system.net.sockets.socket.poll?view=net-10.0" target="_blank" rel="noreferrer">Socket.Poll</a></p><p><a href="/study/os/memory-mapped-files.html">メモリマップドファイル</a>は、ファイルの範囲を仮想アドレス空間へ対応付ける別のアクセス方式です。マッピングしただけで全データの読取りが完了したり、非同期readを発行したりしたことにはなりません。ビューへのアクセス自体でページの準備やI/Oを待つ場合があるため、このページの「要求を発行して後から完了を回収する」手順と区別します。<a href="https://learn.microsoft.com/en-us/windows/win32/memory/file-mapping" target="_blank" rel="noreferrer">Microsoft: File Mapping</a></p><h2 id="同期・非同期と、並列実行は別の軸" tabindex="-1">同期・非同期と、並列実行は別の軸 <a class="header-anchor" href="#同期・非同期と、並列実行は別の軸" aria-label="Permalink to &quot;同期・非同期と、並列実行は別の軸&quot;">​</a></h2><p>同期読み取りは、操作の完了や失敗を待ってから呼出し元へ戻ります。非同期読み取りは、未完了の要求を保持し、後から完了を受け取る仕組みを持ちます。そこで空いた時間を、別の計算や別の要求の処理へ使える場合があります。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/synchronous-and-asynchronous-i-o" target="_blank" rel="noreferrer">Microsoft: Synchronous and Asynchronous I/O</a></p><p>非同期という名前だけでは、複数CPUでの並列実行、常に即座の復帰、読み込み時間の短縮を保証しません。キャッシュなどで即時に完了する場合もあれば、非同期用のハンドルでも開始呼出しが待つ場合があります。小さい処理では、要求や完了を管理する負担が利益を上回ることもあります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-readfile" target="_blank" rel="noreferrer">Microsoft: ReadFile — asynchronous handles</a></p><figure class="study-figure"><img src="'+s+'" alt="同期では読取り呼出しの完了を待つのに対し、非同期では要求後にバッファへ触れない別処理を行い、後で結果を回収できる例。即時完了とpendingのどちらもあり、並列化や速度向上を保証する図ではない。" width="760" height="1510"><figcaption><strong>要求を出す時点、I/Oが完了する時点、結果を扱う時点を分ける。</strong> 図の長さや別処理との重なり方は説明用です。I/Oが即時に完了する場合もあります。<a href="/study/images/io/sync-async-timeline.svg" target="_blank" rel="noopener noreferrer">同期と非同期の時間軸を拡大</a></figcaption></figure><h2 id="windowsでは要求ごとの情報を渡す" tabindex="-1">Windowsでは要求ごとの情報を渡す <a class="header-anchor" href="#windowsでは要求ごとの情報を渡す" aria-label="Permalink to &quot;Windowsでは要求ごとの情報を渡す&quot;">​</a></h2><p>Windowsでは<code>CreateFileW</code>で<code>FILE_FLAG_OVERLAPPED</code>を指定して開き、<code>ReadFile</code>へ<strong>OVERLAPPED</strong>構造体を渡す経路があります。要求の開始位置は<code>Offset</code>と<code>OffsetHigh</code>で指定する、先頭からの64bitのbyteオフセットです。同期版の現在位置が自動で進む仕組みを、そのまま使うものではありません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/minwinbase/ns-minwinbase-overlapped" target="_blank" rel="noreferrer">Microsoft: OVERLAPPED</a></p><table tabindex="0"><thead><tr><th>要求ごとに管理するもの</th><th>役割</th></tr></thead><tbody><tr><td>開いたファイルのハンドル</td><td>どの読み取り元に対する要求か</td></tr><tr><td>オフセット・要求数</td><td>どこから最大何byte読むか</td></tr><tr><td><code>OVERLAPPED</code></td><td>その要求を識別し、状態や完了通知を関連付ける情報</td></tr><tr><td>イベントなどの通知先</td><td>完了したことを受け取る手段</td></tr><tr><td>受取バッファ</td><td>完了後に今回のbyteを受け取る領域</td></tr></tbody></table><p>同時に処理中の要求には、それぞれ有効な要求情報と、重複して使わない受取領域を用意します。まだ処理中の<code>OVERLAPPED</code>を書き換えて次の要求へ使ったり、バッファを別用途へ渡したりしません。オフセットもアプリ側で管理する値であり、OSが要求後に次の位置へ書き換えるフィールドではありません。</p><h3 id="irpと、アプリの要求情報は同じものではない" tabindex="-1">IRPと、アプリの要求情報は同じものではない <a class="header-anchor" href="#irpと、アプリの要求情報は同じものではない" aria-label="Permalink to &quot;IRPと、アプリの要求情報は同じものではない&quot;">​</a></h3><p>Windowsのカーネル側には、ドライバーへI/Oを渡す<strong>IRP</strong>（I/O Request Packet）があります。複数のドライバーを通り、途中の層で完了する場合もあります。アプリが渡す<code>OVERLAPPED</code>そのものがIRP、という関係ではありません。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/i-o-request-packets" target="_blank" rel="noreferrer">Microsoft: I/O Request Packets</a></p><p>読み取りにはIRPを使う経路のほか、fast I/Oの経路もあります。キャッシュの利用や下位デバイスへの要求も関わるため、<strong>アプリのAPI一回、IRP一個、物理ストレージアクセス一回を一対一に数えることはできません。</strong> 非同期指定も、OSのファイルキャッシュを無効にする指示ではありません。<a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/ifs/operations-that-can-be-irp-based-or-fast-i-o" target="_blank" rel="noreferrer">Microsoft: IRP-based or Fast I/O operations</a></p><h2 id="readfileの開始結果を三つに分ける" tabindex="-1">ReadFileの開始結果を三つに分ける <a class="header-anchor" href="#readfileの開始結果を三つに分ける" aria-label="Permalink to &quot;ReadFileの開始結果を三つに分ける&quot;">​</a></h2><p>非同期用に開いたハンドルでの<code>ReadFile</code>は、戻り値だけを「成功／失敗」の二択として読むと誤ります。<code>FALSE</code>の場合は直後の<code>GetLastError</code>を確認します。</p><table tabindex="0"><thead><tr><th>開始呼出しの結果</th><th>意味</th><th>次の扱い</th></tr></thead><tbody><tr><td><code>TRUE</code></td><td>読み取りが即時に成功完了した</td><td>実際数と結果を確認して処理する</td></tr><tr><td><code>FALSE</code>＋<code>ERROR_IO_PENDING</code></td><td>要求が未完了として受理された</td><td>寿命を保って完了を回収する</td></tr><tr><td><code>FALSE</code>＋その他のエラー</td><td>開始時に失敗したなど</td><td>EOFを区別し、エラーを処理する</td></tr></tbody></table><p><code>ERROR_IO_PENDING</code>は、読取り失敗を示すコードではありません。また<code>TRUE</code>だったことだけから、キャッシュヒットや物理I/Oの有無を特定することもできません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-readfile" target="_blank" rel="noreferrer">Microsoft: ReadFile — Return value</a></p><h3 id="イベントとgetoverlappedresult" tabindex="-1">イベントとGetOverlappedResult <a class="header-anchor" href="#イベントとgetoverlappedresult" aria-label="Permalink to &quot;イベントとGetOverlappedResult&quot;">​</a></h3><p>単純なイベント方式では、<code>OVERLAPPED.hEvent</code>へ要求に対応するイベントを設定します。Microsoftの説明では手動リセットイベントを使う方針で、自動リセットイベントと待機の組合せには注意が必要です。イベントの通知は<strong>完了を知らせるもので、成功の保証ではありません。</strong> 成功・失敗と実際に転送された数は、結果を受け取って確認します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/minwinbase/ns-minwinbase-overlapped" target="_blank" rel="noreferrer">Microsoft: OVERLAPPED — hEvent</a></p><p><code>GetOverlappedResult</code>は、対応するハンドルと<code>OVERLAPPED</code>を使って結果を取得します。<strong>最後の引数が<code>TRUE</code>で、まだpendingなら、この呼出し側は完了までブロックします。</strong> 非同期で開始した後でも、結果が必要になった地点で同期的に待つことはあります。<code>FALSE</code>で未完了を調べた場合の<code>ERROR_IO_INCOMPLETE</code>とも区別します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-getoverlappedresult" target="_blank" rel="noreferrer">Microsoft: GetOverlappedResult</a></p><p>大量の要求を扱う別の手段には、<strong>IOCP</strong>（I/O Completion Port）があります。複数ハンドルの完了通知をキューで受け取る仕組みです。イベント方式とIOCPでは結果の回収手続きが異なるため、通知と要求の対応を保つ設計が必要です。今回のC++実践ではイベント方式を使います。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/i-o-completion-ports" target="_blank" rel="noreferrer">Microsoft: I/O Completion Ports</a></p><p><a href="/study/os/io-completion-ports.html">I/O完了ポートの解説</a>では完了キーと要求ポインターの違いを、<a href="/study/practice/io/iocp-observation.html">C++のIOCP観察例</a>では2件の読み取り結果を一つのポートで受け取る方法を確かめられます。</p><h2 id="完了を回収するまで寿命を保つ" tabindex="-1">完了を回収するまで寿命を保つ <a class="header-anchor" href="#完了を回収するまで寿命を保つ" aria-label="Permalink to &quot;完了を回収するまで寿命を保つ&quot;">​</a></h2><p>要求を出した関数のスコープが終わっても、I/Oがそのバッファを使い終えているとは限りません。<strong>処理中の要求に属するバッファ、OVERLAPPED、イベント、ハンドルを、必要な結果回収まで有効に保つ</strong>所有関係を作ります。</p><p>特に、要求を出した直後にローカル配列の寿命を終える、同じ領域へ次の読み取りを重ねる、未完了の受取バッファを表示・解析する、といった扱いは避けます。成功が確認できたら、実際数の範囲だけを処理します。短い読み取りでも、バッファ全体が今回の結果になるわけではありません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-readfile" target="_blank" rel="noreferrer">Microsoft: ReadFile — buffer lifetime</a></p><figure class="study-figure"><img src="'+i+`" alt="要求の作成から発行、pending中、結果回収、再利用や破棄まで、バッファとOVERLAPPEDなどを有効に保つ図。キャンセル要求だけでは寿命が終わらず、成功・キャンセル・別エラーの終端結果を確認する必要がある。" width="760" height="1510"><figcaption><strong>要求の終了を確かめることが、再利用・解放の境界になる。</strong> キャンセルを要求した時点と、要求の終端結果を回収した時点を区別します。<a href="/study/images/io/async-request-lifetime.svg" target="_blank" rel="noopener noreferrer">非同期要求と寿命の図を拡大</a></figcaption></figure><h3 id="cancelioexは完了待ちではない" tabindex="-1">CancelIoExは完了待ちではない <a class="header-anchor" href="#cancelioexは完了待ちではない" aria-label="Permalink to &quot;CancelIoExは完了待ちではない&quot;">​</a></h3><p><code>CancelIoEx</code>は、対象の進行中のI/Oにキャンセルを要求します。成功して戻っても、キャンセル対象のI/Oがすべて完了するまで待ったことにはなりません。<strong>キャンセル要求後も、OVERLAPPEDやバッファをすぐ解放・再利用しません。</strong> 対応する完了を確認して終端結果を回収します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-cancelioex" target="_blank" rel="noreferrer">Microsoft: CancelIoEx</a></p><p>キャンセルと通常完了は競走します。最終結果は、通常の成功、<code>ERROR_OPERATION_ABORTED</code>によるキャンセル、別のエラーのいずれにもなり得ます。<code>ERROR_NOT_FOUND</code>も、「今後その要求の結果を確認しなくてよい」という印ではありません。キャンセル対象が既に見つからない場合にも、所有している要求の最終状態を別に把握する必要があります。</p><p><a href="/study/os/cancelling-overlapped-io.html">非同期I/Oのキャンセル</a>では、新しい発行を止め、完了を回収してからワーカーやバッファを片付ける順序を追います。</p><h2 id="eofと短い読み取りも、完了結果として扱う" tabindex="-1">EOFと短い読み取りも、完了結果として扱う <a class="header-anchor" href="#eofと短い読み取りも、完了結果として扱う" aria-label="Permalink to &quot;EOFと短い読み取りも、完了結果として扱う&quot;">​</a></h2><p>同期<code>ReadFile</code>の「成功して実際数0」というEOF判定を、OVERLAPPED版へそのまま移しません。非同期版では、開始時や結果の回収時に<code>ERROR_HANDLE_EOF</code>としてEOFを受け取る場合があります。通常のエラーと区別して読み取りを終えます。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/testing-for-the-end-of-a-file" target="_blank" rel="noreferrer">Microsoft: Testing for the End of a File</a></p><p>末尾までの残りが要求数より少なければ、その分だけ成功して返ることもあります。読み取れた部分を処理し、必要な長さに足りるかはアプリの形式に従って検査します。byteの内容、要求数と実際数の扱いは<a href="/study/os/file-read-journey.html">同期ファイル読取りの記事</a>と共通ですが、完了を受け取る契約を混同しません。</p><p>TCPの正の長さを要求した通常の<code>recv</code>では、相手が送信を正常終了し、届いているデータを読み終えると0を受け取ります。接続リセットなどのエラーや、自分の送信方向を閉じる操作とは別です。ファイルの<code>ERROR_HANDLE_EOF</code>判定を流用せず、<a href="/study/practice/network/tcp-loopback-observation.html">ループバック実践</a>で受信の終端と応答を確かめます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-recv" target="_blank" rel="noreferrer">Microsoft: recv</a></p><h2 id="c-のreadasyncと、一度だけのawait" tabindex="-1">C#のReadAsyncと、一度だけのawait <a class="header-anchor" href="#c-のreadasyncと、一度だけのawait" aria-label="Permalink to &quot;C#のReadAsyncと、一度だけのawait&quot;">​</a></h2><p>今回のWindows向けC#例は、<code>FileOptions.Asynchronous</code>で開いた<code>FileStream</code>を使います。<code>ReadAsync(Memory&lt;byte&gt;, ...)</code>は<code>ValueTask&lt;int&gt;</code>を返し、結果の整数が実際に読めた数です。正の数を要求したときの0はEOFで、要求より少ない正の数が返る場合もあります。<a href="https://learn.microsoft.com/en-us/dotnet/api/system.io.fileoptions?view=net-10.0" target="_blank" rel="noreferrer">Microsoft: FileOptions</a>、<a href="https://learn.microsoft.com/en-us/dotnet/api/system.io.filestream.readasync?view=net-10.0" target="_blank" rel="noreferrer">FileStream.ReadAsync</a></p><p>次は<code>async</code>メソッド内の要点です。<code>stream</code>は上記の<code>FileStream</code>、<code>buffer</code>は<code>byte[]</code>とします。</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> operation</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stream.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ReadAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(buffer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AsMemory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ここで、このバッファに触れない短い別の処理を行うことはできる。</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> actual</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> operation;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 成功後、bufferの先頭actual bytesだけを使う。</span></span></code></pre></div><p><code>await</code>に到達した時点で未完了なら、その<code>async</code>メソッドは中断し、呼出し元へ制御を戻せます。<code>await</code>がスレッドを待機で塞ぐのではありません。既に完了していれば、中断せず結果を受け取ります。<strong><code>await</code>ごとに別のスレッドを新設する、という仕組みではありません。</strong><a href="https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/operators/await" target="_blank" rel="noreferrer">Microsoft: await operator</a></p><p>この<code>ValueTask&lt;int&gt;</code>は<strong>一度だけawaitして消費</strong>します。繰り返しawaitしたり、未完了の<code>Result</code>を読んだりする使い方へ変更しません。呼出し時や結果受取り時の失敗、キャンセルの例外も処理します。<a href="https://learn.microsoft.com/en-us/dotnet/api/system.threading.tasks.valuetask-1?view=net-10.0" target="_blank" rel="noreferrer">Microsoft: ValueTaskの利用規則</a></p><p><code>Memory&lt;byte&gt;</code>を渡しても、元の配列の内容がコピーされて独立した読み取り先になるわけではありません。要求の終端まで元の領域の寿命と利用規則を保ちます。トークンを通じてキャンセルを要求しただけで、配列を別の処理へ返してよいわけでもありません。<a href="https://learn.microsoft.com/en-us/dotnet/standard/memory-and-spans/memory-t-usage-guidelines" target="_blank" rel="noreferrer">Microsoft: Memoryの利用ガイド</a></p><h3 id="コンパイラとランタイムがつなぐもの" tabindex="-1">コンパイラとランタイムがつなぐもの <a class="header-anchor" href="#コンパイラとランタイムがつなぐもの" aria-label="Permalink to &quot;コンパイラとランタイムがつなぐもの&quot;">​</a></h3><p>コンパイラは<code>async</code>メソッドを、中断位置と再開に必要な状態を保持する<strong>状態機械</strong>へ変換します。未完了の<code>await</code>では継続を登録し、完了後に残りを進めます。スレッドを丸ごと保存して専有し続ける仕組みではありません。<a href="https://devblogs.microsoft.com/dotnet/how-async-await-really-works/" target="_blank" rel="noreferrer">Microsoft .NET Blog: async/awaitの内部</a></p><p>Windows版.NET <strong>v10.0.0の実装例</strong>では、OSへの読み取りが必要になると、<code>ReadAtOffsetAsync</code>から<code>QueueAsyncReadFile</code>へ進みます。ハンドルをスレッドプールのI/O通知へ結び付け、完了結果を保持するオブジェクトが<code>NativeOverlapped</code>とバッファを準備して<code>ReadFile</code>を呼びます。完了コールバックと発行側が連携し、読めた数や失敗を<code>ValueTask</code>へ伝えます。C++例でアプリがイベントを扱う部分を、そのままC#で手書きするわけではありません。<a href="https://github.com/dotnet/runtime/blob/v10.0.0/src/libraries/System.Private.CoreLib/src/System/IO/RandomAccess.Windows.cs" target="_blank" rel="noreferrer">.NET: 読み取りの発行</a>、<a href="https://github.com/dotnet/runtime/blob/v10.0.0/src/libraries/System.Private.CoreLib/src/Microsoft/Win32/SafeHandles/SafeFileHandle.OverlappedValueTaskSource.Windows.cs" target="_blank" rel="noreferrer">完了通知とValueTaskの接続</a></p><p>一方、<code>FileStream</code>内部のバッファだけで要求を満たし、OSへ新たに要求せず完了する経路もあります。<strong>即時完了だけで経路は特定できません。</strong> これは公開実装を読んだ説明であり、実践コードの全要求を追跡した記録ではありません。<a href="https://github.com/dotnet/runtime/blob/v10.0.0/src/libraries/System.Private.CoreLib/src/System/IO/Strategies/BufferedFileStreamStrategy.cs" target="_blank" rel="noreferrer">.NET: 緩衝読み取りの実装</a></p><h3 id="result、wait、task-runとの違い" tabindex="-1">Result、Wait、Task.Runとの違い <a class="header-anchor" href="#result、wait、task-runとの違い" aria-label="Permalink to &quot;Result、Wait、Task.Runとの違い&quot;">​</a></h3><p><code>Task</code>の<code>Result</code>や<code>Wait()</code>で未完了の結果を同期的に待つと、呼出し側のスレッドを塞ぎます。<code>await</code>と同じ待ち方ではありません。また<code>Task.Run</code>へ同期<code>Read</code>を渡す方法は、スレッドプール側で同期読み取りを行わせるもので、その仕事はI/O待ちでワーカーを占有し得ます。OSの非同期I/Oを使う要求と同じ経路とはみなしません。<a href="https://learn.microsoft.com/en-us/dotnet/csharp/asynchronous-programming/async-scenarios" target="_blank" rel="noreferrer">Microsoft: Asynchronous programming scenarios</a></p><h2 id="i-o完了と、ゲームで利用できる時点" tabindex="-1">I/O完了と、ゲームで利用できる時点 <a class="header-anchor" href="#i-o完了と、ゲームで利用できる時点" aria-label="Permalink to &quot;I/O完了と、ゲームで利用できる時点&quot;">​</a></h2><p><strong>I/O完了、継続処理の実行、アセットの利用可能化は別の段階</strong>です。継続処理（continuation）は、完了後に進める残りの処理です。通知を受けても、いつ・どのスレッドでその処理を実行するかは、ランタイムや実行文脈にも依存します。</p><p>アセットのbyteが届いた後にも、展開、デコード、データ構造の構築、GPUへの転送などが残ります。メインスレッドで行う必要のあるエンジンAPIや登録処理は、その条件を守って接続します。今回の確認はコンソール／.NETの例であり、UnityやUIの実行文脈での再開動作を検証したものではありません。</p><p>GPUが使う資源の解放も、CPU側の読取り完了や参照数だけでは決められません。例えばD3D12では、使用を含むGPU処理の完了をフェンスで追跡し、再利用・解放できる時点を管理します。具体的な同期方法はAPIの契約に従います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/fence-based-resource-management" target="_blank" rel="noreferrer">Microsoft: Fence-Based Resource Management</a></p><p>Readyの条件、登録する段階、要求の世代、所有権と解放をまとめた設計は<a href="/study/game/asset-loading.html">実行時のアセットロード</a>を参照してください。<a href="/study/practice/assets/asset-lifecycle-model.html">状態と寿命の観察例</a>は、単一スレッドの決定的なモデルです。実際のI/Oやワーカー、GPU、Unityでの完了・スレッド動作を検証するサンプルではありません。</p><p>要求を増やし続けると、未完了バッファや要求情報も増えます。<strong>バックプレッシャー</strong>は、新規発行を待たせるなどして処理中の量を制限する考え方です。同時要求数や保持するbyte数に予算を設け、完了後の処理が追い付く量に抑えます。Windowsの<code>ReadFile</code>にも、未処理の非同期要求が多すぎる場合のメモリ関連の失敗が記載されています。<a href="https://learn.microsoft.com/en-us/windows/win32/api/fileapi/nf-fileapi-readfile" target="_blank" rel="noreferrer">Microsoft: ReadFile — outstanding requests</a></p><h2 id="実践記事で確かめる範囲" tabindex="-1">実践記事で確かめる範囲 <a class="header-anchor" href="#実践記事で確かめる範囲" aria-label="Permalink to &quot;実践記事で確かめる範囲&quot;">​</a></h2><p><a href="/study/practice/io/async-file-read-observation.html">同期版と非同期版のファイル読み取りを比較する</a>では、同じ12byteの固定データを、同期・非同期それぞれのハンドルやストリームで読みます。即時完了でもpendingでも受け入れ、5byteの要求、短い別計算、結果回収、内容の一致を確かめます。キャンセルの競走は実演せず、上記はAPI契約として説明しています。</p><p>小さなファイルやwarm cacheでは、I/Oが別計算より先に終わることもあります。<code>ValueTask</code>の状態ログも検査時点の状態であり、呼出しから戻った厳密な瞬間を証明しません。この確認だけで、物理I/Oの発生、必ず処理が重なったこと、速度向上を証明したとはしません。</p>`,59)])])}const g=a(n,[["render",d]]);export{m as __pageData,g as default};
